import six
from ute_common_abstract_core.singleton import Singleton


def check_if_backend_is_registered(func):
    def wrapper(*args, **kwargs):
        backend_instance = args[0]
        if backend_instance._name is None:
            raise RuntimeError('ta_messaging backend has not been registered')
        return func(*args, **kwargs)
    return wrapper


@six.add_metaclass(Singleton)
class Backend(object):
    def __init__(self):
        self._name = None
        self._ip_getter = None
        self._starting_func = None

    def register(self, name, ip_getter, starting_func):
        if self._name is not None:
            raise RuntimeError('ta_messaging backend already registered: {}'.format(self._name))
        self._name = name
        self._ip_getter = ip_getter
        self._starting_func = starting_func

    @check_if_backend_is_registered
    def get_ip(self):
        return self._ip_getter()

    @check_if_backend_is_registered
    def run_startup_func(self, tcp_port):
        self._starting_func(tcp_port)
